package com.nexusrpg.world.ent;
import java.util.*; import net.minecraft.init.Blocks; import net.minecraft.world.World; import net.minecraft.world.chunk.Chunk; import net.minecraft.util.math.BlockPos; import com.nexusrpg.init.ModBiomes; import net.minecraftforge.event.world.ChunkDataEvent;
public class EntClearingHarness {
 static void ok(boolean b,String m){if(!b)throw new AssertionError(m);} static long seed(){for(long n=0;n<100000;n++)if(new Random(n ^ 0x454e545f434c5247L).nextInt(80)==0)return n; throw new AssertionError();}
 static Chunk c(){return new Chunk(0,0,ModBiomes.ENCHANTED_GROVE,64);} static World w(Chunk c){World w=new World(c);w.seed=seed();return w;} static void run(EntClearingGenerator g,Chunk c,World w){g.generate(new Random(1),0,0,w,null,(x,z)->x==0&&z==0?c:null);}
 public static void main(String[]a){Chunk c=c();World w=w(c);EntClearingGenerator g=new EntClearingGenerator();run(g,c,w);ok(w.spawns==1,"spawn");ok(w.writes.size()==12,"runes");for(BlockPos p:w.writes)ok((p.getX()>>4)==0&&(p.getZ()>>4)==0,"chunk write");run(g,c,w);ok(w.spawns==1&&w.writes.size()==12,"repeat");
 for(String mode:new String[]{"remote","dimension","features","biome","border","tree","building","tile","entity","collision","saved","badFoundation","flower","spawnCancel","writeFail","foreignPlan"}){c=c();w=w(c);g=new EntClearingGenerator();if(mode.equals("remote"))w.isRemote=true;if(mode.equals("dimension"))w.provider.dim=1;if(mode.equals("features"))w.mapFeatures=false;if(mode.equals("biome"))c.biome=ModBiomes.FROST_CROWN;if(mode.equals("border"))w.border=false;if(mode.equals("tree"))c.overlay.put(new BlockPos(4,65,4),Blocks.LOG.getDefaultState());if(mode.equals("building"))c.overlay.put(new BlockPos(4,40,4),Blocks.PLANKS.getDefaultState());if(mode.equals("tile"))c.tiles.put(new BlockPos(4,40,4),new net.minecraft.tileentity.TileEntityChest());if(mode.equals("entity"))w.entity=true;if(mode.equals("collision"))w.collision=true;if(mode.equals("saved"))g.onChunkDataLoad(new ChunkDataEvent.Load(w,c));if(mode.equals("badFoundation"))c.overlay.put(new BlockPos(4,61,4),Blocks.AIR.getDefaultState());if(mode.equals("flower"))c.overlay.put(new BlockPos(4,64,4),Blocks.YELLOW_FLOWER.getDefaultState());if(mode.equals("spawnCancel"))w.spawnResult=false;if(mode.equals("writeFail"))w.failFloor=true;if(mode.equals("foreignPlan")){w.chestFailure="foreignPlan";w.mutation=new BlockPos(4,64,4);}run(g,c,w);ok(w.spawns==(mode.equals("spawnCancel")?1:0),mode+" spawn");if(mode.equals("foreignPlan"))ok(c.getBlockState(w.mutation).getBlock()==Blocks.LOG,"foreign block preserved");if(mode.equals("spawnCancel")||mode.equals("collision"))for(int x=4;x<=12;x++)for(int z=4;z<=12;z++)for(int y=64;y<=65;y++)ok(c.getBlockState(new BlockPos(x,y,z)).getBlock()==Blocks.AIR,mode+" rollback");}
 System.out.println("PASS success, repeat, 17 guards, spawn cancel, rollback, foreign preservation (simulated)");}
}